def normalize_media(document_blocks, audio_segments, video_frames):
    ocr = normalize_ocr_blocks(document_blocks)
    audio = normalize_audio_segments(audio_segments)
    frames = sample_video_frames(video_frames, interval_ms=1000)
    alignment = align_audio_video(audio, frames, tolerance_ms=500)
    return {'ocr': ocr, 'audio': audio, 'frames': frames, 'alignment': alignment}
